@Module({
  imports: [
    ConfigModule.forRoot(),
  ],
})
export class AppModule {}

// Or in global providers.ts

export const providers: Array<NestModule> = [
  {
    provide: 'loggerMiddleware',
    useFactory: () => ({
      use: LoggerMiddleware,
    }),
  },
