package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"os"

	"github.com/segmentio/avro/go/types"
)

type Schema struct {
	Root struct {
		Fields []Field `json:"fields"`
	} `json:"root"`
}

type Field struct {
	Name   string  `json:"name"`
	Type   types.T `json:"type"`
	Doc    string  `json:"doc,omitempty"`
	Enum   string  `json:"enum,omitempty"`
	Default string `json:"default,omitempty"`
}

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: go run <filename> <struct_name>")
		os.Exit(1)
	}

	fileName := os.Args[1]
	structName := os.Args[2]

	inputFile, err := os.Open(fileName)
	if err != nil {
		panic(err)
	}
	defer inputFile.Close()

	data, err := ioutil.ReadAll(inputFile)
	if err != nil {
		panic(err)
	}

	var schema Schema
	err = json.Unmarshal(data, &schema)
	if err != nil {
		panic(err)
	}

	fieldTypes := make(map[string]types.T)
	for _, field := range schema.Root.Fields {
		fieldTypes[field.Name] = field.Type
	}

	outputData, err := json.MarshalIndent(fieldTypes, "", "  ")
	if err != nil {
		panic(err)
	}

	outFileName := fmt.Sprintf("%s.avsc", structName)
	f, err := os.Create(outFileName)
	if err != nil {
		panic(err)
	}
	defer f.Close()

	_, err = f.Write(outputData)
	if err != nil {
		panic(err)
	}

	fmt.Printf("Generated AVRO schema for %s into %s\n", structName, outFileName)
}
```

